// src/components/portfolio/Portfolio.js
import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import { usePortfolio } from '../../hooks/usePortfolio';
import { tradeAPI } from '../../services/api';

export default function Portfolio() {
  const { portfolioData, loading, error, loadPortfolioData, formatCurrency } = usePortfolio();
  const { isDark } = useTheme();
  const [sandboxLoading, setSandboxLoading] = useState(false);
  const [sandboxMessage, setSandboxMessage] = useState('');
  const [userAccounts, setUserAccounts] = useState([]);
  const [selectedAccount, setSelectedAccount] = useState(null);
  const [accountsLoading, setAccountsLoading] = useState(true);
  const [showAmountInput, setShowAmountInput] = useState(false);
  const [amount, setAmount] = useState('100000');

  // Загружаем список счетов при монтировании компонента
  useEffect(() => {
    loadUserAccounts();
  }, []);

  // Загружаем портфель при выборе счета
  useEffect(() => {
    if (selectedAccount) {
      loadPortfolioData(selectedAccount.id);
    }
  }, [selectedAccount]);

  const loadUserAccounts = useCallback(async () => {
    setAccountsLoading(true);
    try {
      console.log('🔄 Загрузка счетов...');
      const response = await tradeAPI.getAccounts();
      const accounts = response.data || [];

      setUserAccounts(accounts);

      // Автоматически выбираем первый счет, если есть
      if (accounts.length > 0 && !selectedAccount) {
        setSelectedAccount(accounts[0]);
      }

    } catch (error) {
      console.error('❌ Ошибка загрузки счетов:', error);
      setUserAccounts([]);
    } finally {
      setAccountsLoading(false);
    }
  }, [selectedAccount]);

  const handleAccountSelect = useCallback((account) => {
    setSelectedAccount(account);
    setSandboxMessage(`✅ Выбран счет: ${account.id.slice(0, 8)}...`);
  }, []);

  const handleOpenSandboxAccount = useCallback(async () => {
    setSandboxLoading(true);
    setSandboxMessage('');
    try {
      await tradeAPI.openSandboxAccount("ACCOUNT_TYPE_TINKOFF");
      setSandboxMessage('✅ Счет в песочнице успешно создан!');

      // Обновляем список счетов
      setTimeout(loadUserAccounts, 1000);
    } catch (error) {
      console.error('Ошибка создания счета:', error);
      const errorDetail = error.response?.data?.detail;
      setSandboxMessage(`❌ ${errorDetail || 'Ошибка создания счета в песочнице'}`);
    } finally {
      setSandboxLoading(false);
    }
  }, [loadUserAccounts]);

  const handleSandboxPayIn = useCallback(() => {
    if (!selectedAccount) {
      setSandboxMessage('❌ Сначала выберите счет для пополнения');
      return;
    }
    setShowAmountInput(true);
  }, [selectedAccount]);

  const handleConfirmAmount = useCallback(async () => {
    if (!amount || isNaN(amount) || parseFloat(amount) <= 0) {
      setSandboxMessage('❌ Введите корректную сумму');
      setShowAmountInput(false);
      return;
    }

    setShowAmountInput(false);
    await processPayIn(selectedAccount.id, parseFloat(amount));
  }, [amount, selectedAccount]);

  const processPayIn = useCallback(async (accountId, amount) => {
    setSandboxLoading(true);
    setSandboxMessage('');
    try {
      await tradeAPI.sandboxPayIn(accountId, amount, "RUB");
      setSandboxMessage(`✅ Счет пополнен на ${amount} рублей!`);

      // Перезагружаем портфель
      setTimeout(() => loadPortfolioData(accountId), 1000);
    } catch (error) {
      console.error('Ошибка пополнения счета:', error);
      const errorDetail = error.response?.data?.detail;
      setSandboxMessage(`❌ ${errorDetail || 'Ошибка пополнения счета'}`);
    } finally {
      setSandboxLoading(false);
    }
  }, [loadPortfolioData]);

  const handleCloseAccount = useCallback(async (accountId) => {
    if (!window.confirm('Вы уверены, что хотите закрыть этот счет?')) {
      return;
    }

    setSandboxLoading(true);
    try {
      await tradeAPI.closeAccount(accountId);
      setSandboxMessage('✅ Счет успешно закрыт');

      // Обновляем список счетов
      setTimeout(() => {
        loadUserAccounts();
        if (selectedAccount?.id === accountId) {
          setSelectedAccount(null);
        }
      }, 1000);
    } catch (error) {
      console.error('Ошибка закрытия счета:', error);
      setSandboxMessage(`❌ ${error.response?.data?.detail || 'Ошибка закрытия счета'}`);
    } finally {
      setSandboxLoading(false);
    }
  }, [loadUserAccounts, selectedAccount]);

  // Мемоизированные компоненты для оптимизации
  const AccountCard = useCallback(({ account, isSelected, onSelect, onClose }) => (
    <div
      className={`p-4 rounded-2xl border-2 cursor-pointer transition-all duration-200 ${
        isSelected
          ? isDark
            ? 'border-cyan-500 bg-cyan-500/10'
            : 'border-blue-500 bg-blue-50'
          : isDark
            ? 'border-gray-600 bg-gray-700/50 hover:border-gray-500'
            : 'border-gray-200 bg-gray-50 hover:border-gray-300'
      }`}
      onClick={() => onSelect(account)}
    >
      <div className="flex justify-between items-start mb-2">
        <div>
          <h4 className="font-semibold text-gray-900 dark:text-white">
            {account.name || 'Без названия'}
          </h4>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            ID: {account.id.slice(0, 12)}...
          </p>
        </div>
        {isSelected && (
          <div className={`w-3 h-3 rounded-full ${
            isDark ? 'bg-cyan-500' : 'bg-blue-500'
          }`}></div>
        )}
      </div>
      <div className="flex justify-between items-center text-xs">
        <span className={`px-2 py-1 rounded-full ${
          isDark ? 'bg-gray-600 text-gray-300' : 'bg-gray-200 text-gray-700'
        }`}>
          {account.type || 'Песочница'}
        </span>
        <span className={`px-2 py-1 rounded-full ${
          account.status === 'ACCOUNT_STATUS_OPEN'
            ? isDark ? 'bg-green-500/20 text-green-400' : 'bg-green-100 text-green-700'
            : isDark ? 'bg-red-500/20 text-red-400' : 'bg-red-100 text-red-700'
        }`}>
          {account.status === 'ACCOUNT_STATUS_OPEN' ? 'Открыт' : 'Закрыт'}
        </span>
      </div>
      {isSelected && (
        <button
          onClick={(e) => {
            e.stopPropagation();
            onClose(account.id);
          }}
          className="w-full mt-3 py-1 text-xs text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg transition-colors"
        >
          Закрыть счет
        </button>
      )}
    </div>
  ), [isDark]);

  const ActionButtons = useCallback(() => (
    <div className="flex flex-wrap gap-3">
      <button
        onClick={handleOpenSandboxAccount}
        disabled={sandboxLoading}
        className={`px-4 py-2 rounded-2xl font-semibold text-white bg-white/20 hover:bg-white/30 transition-all duration-300 disabled:opacity-50 ${
          isDark ? 'hover:shadow-lg' : 'hover:shadow-md'
        }`}
      >
        {sandboxLoading ? 'Создание...' : 'Создать счет'}
      </button>
      <button
        onClick={handleSandboxPayIn}
        disabled={sandboxLoading || !selectedAccount}
        className={`px-4 py-2 rounded-2xl font-semibold text-white bg-white/20 hover:bg-white/30 transition-all duration-300 disabled:opacity-50 ${
          isDark ? 'hover:shadow-lg' : 'hover:shadow-md'
        }`}
      >
        {sandboxLoading ? 'Пополнение...' : 'Пополнить счет'}
      </button>
      <button
        onClick={() => selectedAccount && loadPortfolioData(selectedAccount.id)}
        className={`px-4 py-2 rounded-2xl font-semibold text-white bg-white/20 hover:bg-white/30 transition-all duration-300 ${
          isDark ? 'hover:shadow-lg' : 'hover:shadow-md'
        }`}
      >
        Обновить
      </button>
    </div>
  ), [sandboxLoading, selectedAccount, isDark, handleOpenSandboxAccount, handleSandboxPayIn, loadPortfolioData]);

  // Основные метрики портфеля из нового бэкенда
  const portfolioMetrics = useMemo(() => {
    if (!portfolioData?.summary) return null;

    const { summary, performance } = portfolioData;

    return [
      {
        title: "Общая стоимость",
        value: `${formatCurrency(summary.total_value)} ₽`,
        subtitle: "Весь портфель",
        isProfit: false
      },
      {
        title: "Общая доходность",
        value: `${performance.total.value >= 0 ? '+' : ''}${formatCurrency(performance.total.value)} ₽`,
        subtitle: `${performance.total.percent >= 0 ? '+' : ''}${performance.total.percent.toFixed(2)}%`,
        isProfit: true
      },
      {
        title: "Доходность за день",
        value: `${performance.today.value >= 0 ? '+' : ''}${formatCurrency(performance.today.value)} ₽`,
        subtitle: `${performance.today.percent >= 0 ? '+' : ''}${performance.today.percent.toFixed(2)}%`,
        isProfit: true
      },
      {
        title: "Позиций в портфеле",
        value: summary.positions_count,
        subtitle: `${summary.profitable_positions} прибыльных`,
        isProfit: false
      }
    ];
  }, [portfolioData, formatCurrency]);

  const assetAllocation = useMemo(() => {
    if (!portfolioData?.asset_allocation) return null;

    return Object.entries(portfolioData.asset_allocation)
      .filter(([_, percent]) => percent > 0.1) // Фильтруем маленькие проценты
      .sort(([_, a], [__, b]) => b - a); // Сортируем по убыванию
  }, [portfolioData]);

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className={`animate-spin rounded-full h-12 w-12 border-b-2 ${
          isDark ? 'border-cyan-500' : 'border-blue-500'
        }`}></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Модальное окно ввода суммы */}
      {showAmountInput && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className={`rounded-3xl p-6 max-w-md w-full mx-4 ${
            isDark ? 'bg-gray-800' : 'bg-white'
          }`}>
            <h3 className="text-lg font-semibold mb-4 text-gray-900 dark:text-white">
              Пополнение счета
            </h3>
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Введите сумму пополнения (рубли):
              </label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                className={`w-full px-4 py-3 rounded-2xl border ${
                  isDark
                    ? 'bg-gray-700 border-gray-600 text-white'
                    : 'bg-white border-gray-300 text-gray-900'
                } focus:outline-none focus:ring-2 focus:ring-blue-500`}
                placeholder="100000"
                min="1"
                step="1000"
              />
            </div>
            <div className="flex space-x-3">
              <button
                onClick={handleConfirmAmount}
                className={`flex-1 py-3 rounded-2xl font-semibold text-white bg-blue-500 hover:bg-blue-600 transition-all duration-300 ${
                  isDark ? 'hover:shadow-lg' : 'hover:shadow-md'
                }`}
              >
                Пополнить
              </button>
              <button
                onClick={() => setShowAmountInput(false)}
                className={`flex-1 py-3 rounded-2xl font-medium ${
                  isDark
                    ? 'bg-gray-600 hover:bg-gray-500 text-white'
                    : 'bg-gray-200 hover:bg-gray-300 text-gray-900'
                }`}
              >
                Отмена
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Шапка с выбором счета */}
      <div className={`rounded-3xl p-8 text-white shadow-2xl ${
        isDark
          ? 'bg-gradient-to-r from-green-600 to-cyan-600'
          : 'bg-gradient-to-r from-blue-500 to-purple-600'
      }`}>
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
          <div>
            <h1 className="text-3xl font-bold mb-2">Портфель</h1>
            <p className={isDark ? 'text-cyan-100' : 'text-blue-100'}>
              {selectedAccount
                ? `Счет: ${selectedAccount.id.slice(0, 8)}...`
                : 'Выберите счет для просмотра'
              }
            </p>
          </div>
          <ActionButtons />
        </div>
      </div>

      {/* Блок выбора счета */}
      <div className={`rounded-2xl p-6 ${
        isDark ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200 shadow-lg'
      }`}>
        <h3 className="text-lg font-semibold mb-4 text-gray-900 dark:text-white">
          Выбор счета
        </h3>

        {accountsLoading ? (
          <div className="flex items-center justify-center py-4">
            <div className={`animate-spin rounded-full h-6 w-6 border-b-2 mr-3 ${
              isDark ? 'border-cyan-500' : 'border-blue-500'
            }`}></div>
            <p className="text-gray-600 dark:text-gray-300">Загрузка счетов...</p>
          </div>
        ) : userAccounts.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {userAccounts.map((account) => (
              <AccountCard
                key={account.id}
                account={account}
                isSelected={selectedAccount?.id === account.id}
                onSelect={handleAccountSelect}
                onClose={handleCloseAccount}
              />
            ))}
          </div>
        ) : (
          <div className={`text-center py-6 rounded-2xl ${
            isDark ? 'bg-gray-700/50' : 'bg-gray-50'
          }`}>
            <p className="text-gray-600 dark:text-gray-400 mb-4">
              Нет доступных счетов
            </p>
            <button
              onClick={handleOpenSandboxAccount}
              className={`px-4 py-2 rounded-2xl font-semibold ${
                isDark
                  ? 'bg-cyan-600 hover:bg-cyan-500 text-white'
                  : 'bg-blue-500 hover:bg-blue-600 text-white'
              }`}
            >
              Создать первый счет
            </button>
          </div>
        )}
      </div>

      {/* Сообщения */}
      {sandboxMessage && (
        <div className={`p-4 rounded-2xl ${
          sandboxMessage.includes('❌') || sandboxMessage.includes('Ошибка')
            ? 'bg-red-100 border border-red-300 text-red-700 dark:bg-red-900 dark:border-red-700 dark:text-red-200'
            : 'bg-green-100 border border-green-300 text-green-700 dark:bg-green-900 dark:border-green-700 dark:text-green-200'
        }`}>
          {sandboxMessage}
        </div>
      )}

      {error && (
        <div className={`rounded-2xl p-4 border ${
          isDark ? 'bg-red-500/10 border-red-500/30 text-red-300' : 'bg-red-50 border-red-200 text-red-700'
        }`}>
          <div className="flex items-center">
            <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            {error}
          </div>
        </div>
      )}

      {/* Основная информация о портфеле */}
      {selectedAccount && portfolioData ? (
        <>
          {/* Основные метрики */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {portfolioMetrics?.map((metric, index) => (
              <div key={index} className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
                <p className="text-sm font-medium text-gray-600 dark:text-gray-400">{metric.title}</p>
                <p className={`text-2xl font-bold mt-1 ${
                  metric.isProfit
                    ? (metric.value.includes('+')
                        ? 'text-green-600 dark:text-green-400'
                        : 'text-red-600 dark:text-red-400')
                    : 'text-gray-900 dark:text-white'
                }`}>
                  {metric.value}
                </p>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">{metric.subtitle}</p>
              </div>
            ))}
          </div>

          {/* Распределение активов */}
          {assetAllocation && assetAllocation.length > 0 && (
            <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
              <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-4">
                Распределение активов
              </h3>
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
                {assetAllocation.map(([assetType, percent]) => (
                  <div key={assetType} className="text-center">
                    <div className="relative w-16 h-16 mx-auto mb-2">
                      <svg className="w-16 h-16 transform -rotate-90" viewBox="0 0 36 36">
                        <circle cx="18" cy="18" r="16" fill="none" className="stroke-gray-200 dark:stroke-gray-700" strokeWidth="2"/>
                        <circle cx="18" cy="18" r="16" fill="none" className="stroke-blue-500" strokeWidth="2" strokeDasharray="100" strokeDashoffset={100 - percent}/>
                      </svg>
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-sm font-bold text-gray-900 dark:text-white">
                          {percent.toFixed(1)}%
                        </span>
                      </div>
                    </div>
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-400 capitalize">
                      {assetType === 'cash' ? 'Деньги' :
                       assetType === 'stock' ? 'Акции' :
                       assetType === 'bond' ? 'Облигации' :
                       assetType === 'etf' ? 'ETF' : assetType}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Детали портфеля */}
          <PortfolioDetails
            positions={portfolioData.positions}
            isDark={isDark}
            formatCurrency={formatCurrency}
          />
        </>
      ) : selectedAccount ? (
        <div className={`rounded-2xl p-8 text-center ${
          isDark ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200 shadow-lg'
        }`}>
          <div className={`w-16 h-16 mx-auto mb-4 rounded-2xl flex items-center justify-center ${
            isDark ? 'bg-gray-700' : 'bg-gray-100'
          }`}>
            <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
            </svg>
          </div>
          <h4 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
            Загрузка портфеля...
          </h4>
        </div>
      ) : (
        <div className={`rounded-2xl p-8 text-center ${
          isDark ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200 shadow-lg'
        }`}>
          <div className={`w-16 h-16 mx-auto mb-4 rounded-2xl flex items-center justify-center ${
            isDark ? 'bg-gray-700' : 'bg-gray-100'
          }`}>
            <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
            </svg>
          </div>
          <h4 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
            Выберите счет для просмотра портфеля
          </h4>
          <p className="text-gray-600 dark:text-gray-400">
            Выберите счет из списка выше, чтобы увидеть детальную информацию о ваших инвестициях
          </p>
        </div>
      )}
    </div>
  );
}

// Оптимизированный компонент деталей портфеля
const PortfolioDetails = React.memo(({ positions, isDark, formatCurrency }) => {
  if (!positions || positions.length === 0) {
    return (
      <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-8 text-center">
        <div className={`w-16 h-16 mx-auto mb-4 rounded-2xl flex items-center justify-center ${
          isDark ? 'bg-gray-700' : 'bg-gray-100'
        }`}>
          <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
        </div>
        <h4 className="text-lg font-medium text-gray-900 dark:text-white mb-2">Портфель пуст</h4>
        <p className="text-gray-600 dark:text-gray-400 max-w-sm mx-auto">
          Начните инвестировать, чтобы увидеть свои позиции здесь.
          Используйте раздел "Торговля" для покупки акций.
        </p>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 overflow-hidden">
      <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center">
        <h3 className="text-xl font-semibold text-gray-800 dark:text-white">Позиции в портфеле</h3>
        <span className="text-sm text-gray-500 dark:text-gray-400">
          Обновлено: {new Date().toLocaleTimeString('ru-RU')}
        </span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className={`border-b border-gray-200 dark:border-gray-700 ${
              isDark ? 'bg-gray-700/50' : 'bg-gray-50'
            }`}>
              <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Актив</th>
              <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Количество</th>
              <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Средняя цена</th>
              <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Текущая цена</th>
              <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Стоимость</th>
              <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Доходность</th>
            </tr>
          </thead>
          <tbody>
            {positions.map((position, index) => (
              <PortfolioRow
                key={`${position.figi}-${index}`}
                position={position}
                isDark={isDark}
                formatCurrency={formatCurrency}
              />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
});

const PortfolioRow = React.memo(({ position, isDark, formatCurrency }) => {
  const isProfit = position.expected_yield >= 0;
  const isCash = position.is_cash;

  return (
    <tr className={`border-b border-gray-200 dark:border-gray-700 hover:${
      isDark ? 'bg-gray-700/30' : 'bg-gray-50'
    } transition-colors duration-200`}>
      <td className="py-4 px-6">
        <div className="flex items-center space-x-3">
          <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${
            isCash
              ? (isDark ? 'bg-gray-500/20' : 'bg-gray-100')
              : isProfit
                ? (isDark ? 'bg-green-500/20' : 'bg-green-100')
                : (isDark ? 'bg-red-500/20' : 'bg-red-100')
          }`}>
            <span className={`font-bold text-sm ${
              isCash
                ? (isDark ? 'text-gray-400' : 'text-gray-600')
                : isProfit
                  ? (isDark ? 'text-green-400' : 'text-green-600')
                  : (isDark ? 'text-red-400' : 'text-red-600')
            }`}>
              {position.ticker}
            </span>
          </div>
          <div>
            <p className="font-semibold text-gray-800 dark:text-white">
              {position.name || position.ticker}
            </p>
            <p className="text-sm text-gray-600 dark:text-gray-400 capitalize">
              {position.instrument_type === 'cash' ? 'Денежные средства' : position.instrument_type}
            </p>
          </div>
        </div>
      </td>
      <td className="py-4 px-6 text-gray-800 dark:text-white">
        {isCash ? formatCurrency(position.quantity) : `${position.quantity.toLocaleString('ru-RU')} шт`}
      </td>
      <td className="py-4 px-6 text-gray-800 dark:text-white">
        {isCash ? '-' : `${formatCurrency(position.average_price)} ₽`}
      </td>
      <td className="py-4 px-6 text-gray-800 dark:text-white">
        {isCash ? '1.00 ₽' : `${formatCurrency(position.price)} ₽`}
      </td>
      <td className="py-4 px-6 text-gray-800 dark:text-white">
        {formatCurrency(position.value)} ₽
      </td>
      <td className="py-4 px-6">
        {!isCash && (
          <div className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium ${
            isProfit
              ? (isDark ? 'bg-green-500/20 text-green-400' : 'bg-green-100 text-green-700')
              : (isDark ? 'bg-red-500/20 text-red-400' : 'bg-red-100 text-red-700')
          }`}>
            {isProfit ? '+' : ''}{formatCurrency(position.expected_yield)} ₽
            <span className="ml-1">
              ({isProfit ? '+' : ''}{position.yield_percent?.toFixed(2) || '0.00'}%)
            </span>
          </div>
        )}
      </td>
    </tr>
  );
});
